[{"order":1,"type":"heading","text":"Distributed Tracing, Metrics, and Observability in Java Apps"},{"order":2,"type":"paragraph","text":"Observability is a critical pillar of modern cloud-native architectures. In a distributed system, understanding how a request flows through multiple microservices requires more than traditional logging. This tutorial covers how to implement distributed tracing, expose metrics, and achieve comprehensive observability in Java applications using Micrometer and OpenTelemetry."},{"order":3,"type":"subheading","text":"1. Understanding the Three Pillars"},{"order":4,"type":"paragraph","text":"Observability rests on three foundational pillars: Metrics (numerical values aggregated over time), Logs (discrete events with context), and Traces (the end-to-end journey of a request across services). Java provides robust ecosystems like Micrometer for metrics and OpenTelemetry for distributed tracing."},{"order":5,"type":"subheading","text":"2. Adding Dependencies"},{"order":6,"type":"paragraph","text":"To get started in a Spring Boot application, add the required dependencies for Micrometer tracing and OpenTelemetry bridge in your pom.xml file."},{"order":7,"type":"code","text":"<dependency>
    <groupId>io.micrometer</groupId>
    <artifactId>micrometer-tracing-bridge-otel</artifactId>
</dependency>
<dependency>
    <groupId>io.opentelemetry</groupId>
    <artifactId>opentelemetry-exporter-otlp</artifactId>
</dependency>
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-actuator</artifactId>
</dependency>"},{"order":8,"type":"subheading","text":"3. Configuring Application Properties"},{"order":9,"type":"paragraph","text":"Configure your application to sample all traces and export them using the OTLP protocol. Add the following properties to your application.properties file."},{"order":10,"type":"code","text":"management.tracing.sampling.probability=1.0
management.otlp.tracing.endpoint=http://localhost:4317
management.endpoints.web.exposure.include=health,prometheus,metrics"},{"order":11,"type":"subheading","text":"4. Creating Custom Spans and Metrics"},{"order":12,"type":"paragraph","text":"You can programmatically capture custom metrics and spans using Micrometer's MeterRegistry and Tracer APIs. Below is an example service component that records custom execution time and business metrics."},{"order":13,"type":"code","text":"import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.tracing.Tracer;
import org.springframework.stereotype.Service;

@Service
public class OrderService {
    private final MeterRegistry meterRegistry;
    private final Tracer tracer;
    private final Counter orderCounter;

    public OrderService(MeterRegistry meterRegistry, Tracer tracer) {
        this.meterRegistry = meterRegistry;
        this.tracer = tracer;
        this.orderCounter = Counter.builder("orders.processed"
                ).description("Number of processed orders"
                ).register(meterRegistry);
    }

    public void processOrder(String orderId) {
        orderCounter.increment();
        var span = tracer.nextSpan().name("processOrderSpan").start();
        try (var ws = tracer.withSpan(span)) {
            span.tag("order.id", orderId);
            // Business logic goes here
        } finally {
            span.end();
        }
    }
}"},{"order":14,"type":"subheading","text":"5. Best Practices for Java Observability"},{"order":15,"type":"bullet_point","text":"Always propagate trace context across asynchronous boundaries and thread pools using ContextPropagators."},{"order":16,"type":"bullet_point","text":"Avoid high cardinality tags in metrics to prevent memory leaks in your Prometheus or time-series database."},{"order":17,"type":"bullet_point","text":"Use dynamic sampling rates in production environments to control network bandwidth and storage costs."}]
